(()=>{const url=new URL(location.href);const requested=url.searchParams.get('lang');const current=location.pathname.endsWith('/en.html')?'en':'uk';let preferred;try{preferred=localStorage.getItem('cutline-language');}catch{}const selected=requested==='en'||requested==='uk'?requested:preferred;const explicit=location.pathname.endsWith('/en.html')||location.pathname.endsWith('/index.html');if((requested||!explicit)&&selected&&selected!==current){url.pathname=url.pathname.replace(/[^/]*$/,selected==='en'?'en.html':'index.html');url.searchParams.delete('lang');location.replace(url.href);return;}document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.language-switch a').forEach(link=>link.addEventListener('click',()=>{try{localStorage.setItem('cutline-language',link.lang);}catch{}const target=new URL(link.href);target.hash='';link.href=target.href;try{const blocks=[...document.querySelectorAll('body>header,main>section,body>footer')];let i=blocks.findIndex(b=>b.getBoundingClientRect().bottom>1);if(i<0)i=0;const r=blocks[i].getBoundingClientRect();sessionStorage.setItem('cutline-scroll',JSON.stringify({i,ratio:Math.max(0,-r.top)/Math.max(1,r.height)}));}catch{}}));});try{const saved=JSON.parse(sessionStorage.getItem('cutline-scroll')||'null');if(saved){sessionStorage.removeItem('cutline-scroll');if('scrollRestoration'in history)history.scrollRestoration='manual';const go=()=>{const blocks=[...document.querySelectorAll('body>header,main>section,body>footer')];const b=blocks[saved.i];if(!b)return;const top=b.getBoundingClientRect().top+scrollY+saved.ratio*b.getBoundingClientRect().height;window.scrollTo({top:Math.max(0,Math.round(top)),behavior:'instant'});};document.addEventListener('DOMContentLoaded',go);addEventListener('load',()=>requestAnimationFrame(go));}}catch{}})();
